{"code_completion": "module TopModule (
    input  wire clk,
    input  wire aresetn,
    input  wire x,
    output wire z
);

    localparam [1:0] IDLE = 2'd0, // no useful prefix seen
                     GOT1 = 2'd1, // saw '1'
                     GOT10 = 2'd2; // saw '10'

    reg [1:0] state;

    always @(posedge clk or negedge aresetn) begin
        if (!aresetn) begin
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    if (x) state <= GOT1;
                    else   state <= IDLE;
                end

                GOT1: begin
                    if (x) state <= GOT1;
                    else   state <= GOT10;
                end

                GOT10: begin
                    if (x) state <= GOT1;  // detected "101", final '1' can start next match
                    else   state <= IDLE;
                end

                default: state <= IDLE;
            endcase
        end
    end

    assign z = (state == GOT10) && x;

endmodule"}
